  assert.ok(P.DUR.kindleOff !== P.DUR.drapeOff, "a return, not a slip");
  assert.ok(P.DUR.kindleOff !== P.DUR.tossOff, "a return, not a hop");
  const hold = P.kindlePoint(WIN, P.SPRITE, WORK);
