  assert.ok(!seen.has("coil-hold"), "not Volt");
  assert.ok(!seen.has("ledge-sit"), "not Miso");
  assert.ok(!seen.has("sill-walk"), "not a generic sill");
  assert.equal(windowIds.size, 1, "one window");
  assert.ok(coalXMax - coalXMin < 2, "one ash — not a walk across");
  assert.ok(riseXMax - riseXMin < 2, "one kindle — she rises in place");
  assert.ok(riseLift > 40, "the kindle is visible");
