  assert.ok(Math.abs(target.holdX - forage.x) > 20 || Math.abs(target.holdLift - forage.lift) > 16, "not Thrum");
  assert.ok(Math.abs(target.holdX - curl.x) > 20 || Math.abs(target.holdLift - curl.lift) > 16, "not Dew");
