  assert.ok(P.DUR.droneOff !== P.DUR.lickOff);
  assert.ok(P.DUR.droneOff !== P.DUR.tendOff);
  assert.ok(P.DUR.droneOff !== P.DUR.snipOff);
  assert.ok(P.DUR.droneOff !== P.DUR.daubOff);
