  assert.ok(target.holdLift > 18, "she sits the throat, not the floor");
  assert.ok(P.DUR.ring < P.DUR.ringHold, "the ring is the tell; the hold is the jaw after");
  assert.ok(P.DUR.ringOn !== P.DUR.coverOn);
