  assert.ok(P.DUR.slideOn !== P.DUR.ringOn);
  assert.ok(P.DUR.slideOn !== P.DUR.sillHop);
  assert.ok(P.DUR.slide !== P.DUR.tip);
  assert.ok(P.DUR.slide !== P.DUR.run);
  assert.ok(P.DUR.slide !== P.DUR.circle);
  assert.ok(P.DUR.slideHold !== P.DUR.tipHold);
  assert.ok(P.DUR.slideHold !== P.DUR.runHold);
  assert.ok(P.DUR.slideOff !== P.DUR.tipOff);
  assert.ok(P.DUR.slideOff !== P.DUR.runOff);
