  const hopEase = 0.25 * 0.25 * (3 - 2 * 0.25);
  assert.ok(hopOn.lift > pane.lift * hopEase + 4, "she hops onto the glass");
  const wet = P.slidePath(0.85);
  const dabble = P.tipPath(0.5);
  const bite = P.runPath(0.5);
  const press = P.buryPath(0.45);
  assert.ok(wet.lift < -20, "she slides down the pane once");
  assert.ok(wet.lift < dabble.lift - 10, "a downward slide, not Drake's tip-dabble");
  assert.ok(wet.lift < bite.lift - 10, "a downward slide, not Gale's dash-bite");
  assert.ok(wet.lift < press.lift - 10, "a pane slide, not Cache's stool press");
  assert.ok(Math.abs(wet.x) < 8, "one wet track down the glass, not Coin's circle");
  const still = P.slideHoldPath(0.5);
  assert.ok(still.lift < -65, "she holds wet at the bottom of the slide");
  assert.ok(Math.abs(still.x - 3.6) < 0.2, "the slide stays one track");
  const off0 = P.slideSlipPath(0, { x: pane.x, lift: pane.lift - 72, rot: 16 }, { x: pane.x + 52, lift: 0 });
  const offMid = P.slideSlipPath(0.5, { x: pane.x, lift: pane.lift - 72, rot: 16 }, { x: pane.x + 52, lift: 0 });
