  assert.equal(P.DUR.stillOn, 1.14, "Grin's still durations stay");
  assert.equal(P.DUR.hourOn, 1.44, "Hour's hang durations stay");
  assert.equal(P.DUR.hang, 1.35, "Rui's hang duration stays");
  assert.equal(P.DUR.hookOn, 0.5, "Quill's hook durations stay");
  assert.equal(P.DUR.browseOn, 1.36, "Coal browse durations stay");
  const target = P.pickTarget([WIN], 80, "sloth", WORK, P.SPRITE);
  assert.ok(target);
  assert.equal(target.kind, "reach");
  assert.equal(target.side, "boughhook");
  assert.equal(target.leave, "unhook");
  assert.notEqual(target.kind, "hang");
  assert.notEqual(target.kind, "hook");
  assert.notEqual(target.kind, "fold");
  assert.notEqual(target.kind, "still");
  assert.notEqual(target.kind, "croak");
  assert.notEqual(target.kind, "browse");
