  assert.ok(P.DUR.wrapOn !== P.DUR.reachOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.hang);
  assert.ok(P.DUR.wrapOn !== P.DUR.hookOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.curlOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.sillHop);
  assert.ok(P.DUR.wrap !== P.DUR.sip);
  assert.ok(P.DUR.wrap !== P.DUR.forage);
  assert.ok(P.DUR.wrap !== P.DUR.snip);
  assert.ok(P.DUR.wrap !== P.DUR.drink);
  assert.ok(P.DUR.wrap !== P.DUR.sing);
  assert.ok(P.DUR.wrapHold !== P.DUR.sipHold);
  assert.ok(P.DUR.wrapHold !== P.DUR.singHold);
  assert.ok(P.DUR.wrapOff !== P.DUR.sipOff);
  assert.ok(P.DUR.wrapOff !== P.DUR.singOff);
  assert.ok(P.DUR.wrapOff !== P.DUR.sillDown);
  const cup = P.wrapPoint(WIN, P.SPRITE, WORK);
  const nectar = P.sipPoint(WIN, P.SPRITE, WORK);
  const meadow = P.foragePoint(WIN, P.SPRITE, WORK);
  const foliage = P.snipPoint(WIN, P.SPRITE, WORK);
  const drip = P.drinkPoint(WIN, P.SPRITE, WORK);
  const arm = P.singPoint(WIN, P.SPRITE, WORK);
  const bough = P.reachPoint(WIN, P.SPRITE, WORK);
