  assert.ok(walkOn.lift !== swingOn.lift, "a walk, not Swing's swing");
  assert.ok(walkOn.lift !== forageOn.lift, "a walk, not Thrum's hover");
  const coil = P.wrapPath(0.5);
  const needle = P.sipPath(0.42);
  const song = P.singPath(0.5);
  const buzz = P.foragePath(0.5);
  const circle = P.snipPath(0.5);
  assert.ok(coil.rot > 20, "the tail wraps");
