  assert.ok(Math.abs(coil.x) < 12, "a wrap, not Disc's leaf circle");
  const hold = P.wrapHoldPath(0.5);
  assert.ok(Math.abs(hold.rot - 38) < 0.2, "she holds the wrap");
  assert.ok(Math.abs(hold.x - 6.0) < 0.2, "she holds the tail wrap");
  assert.ok(hold.lift > 3, "wrapped on the bloom, not a floor sit");
  const off0 = P.wrapOffPath(0, { x: cup.x, lift: cup.lift, rot: 38 }, { x: cup.x + 58, lift: 0 });
  const offMid = P.wrapOffPath(0.5, { x: cup.x, lift: cup.lift, rot: 38 }, { x: cup.x + 58, lift: 0 });
  const off1 = P.wrapOffPath(1, { x: cup.x, lift: cup.lift, rot: 38 }, { x: cup.x + 58, lift: 0 });
  const midEase = 0.5 * 0.5 * (3 - 2 * 0.5);
  assert.ok(Math.abs(off0.x - cup.x) < 2);
  assert.ok(Math.abs(offMid.x - (cup.x + 58 * midEase)) < 12, "she unhooks, not a drop");
  assert.ok(Math.abs(off1.lift) < 3);
  let play = P.beginPlay(target, target.approachX);
  const seen = new Set();
  const windowIds = new Set();
  for (let i = 0; i < 2400 && play.phase !== "done"; i++) {
    seen.add(play.phase);
    if (play.target && play.target.id) windowIds.add(play.target.id);
    play = P.stepPlay(play, 0.05, { x: play.x, lift: play.lift }, [WIN, WIN_B], WORK, P.SPRITE, { cmd: "idle" });
    assert.notEqual(play.phase, "sip");
    assert.notEqual(play.phase, "forage");
    assert.notEqual(play.phase, "snip");
    assert.notEqual(play.phase, "drink");
    assert.notEqual(play.phase, "sing");
    assert.notEqual(play.phase, "reach");
    assert.notEqual(play.phase, "sill-walk");
    if (play.phase === "wrap") {
      assert.equal(play.anim, "play");
    }
    if (play.phase === "wrap-on") {
      assert.equal(play.anim, "walk");
    }
    if (play.phase === "wrap-hold" && play.t > 0) {
      assert.equal(play.anim, "sit");
      assert.ok(Math.abs(play.lift - (play.target.holdLift + 4.0)) < 3, "she holds the wrap on the bloom");
    }
    if (play.phase === "wrap-off") {
      assert.equal(play.anim, "walk");
    }
  }
  assert.ok(seen.has("wrap-on"));
  assert.ok(seen.has("wrap"));
  assert.ok(seen.has("wrap-hold"));
  assert.ok(seen.has("wrap-off"));
  assert.ok(!seen.has("sip"), "Wrist never uses Sip's sip");
